    def sumOfGoodNumbers(self, nums: List[int], k: int) -> int:
        total_sum = 0
        n = len(nums)

        for i in range(n):
            is_good = True

            # Check left neighbor (i - k)
            if i - k >= 0:
                if nums[i] <= nums[i - k]:
                    is_good = False

            # Check right neighbor (i + k)
            if i + k < n:
                if nums[i] <= nums[i + k]:
                    is_good = False

            # If it's strictly greater than both neighbors, add to total
            if is_good:
                total_sum += nums[i]

        return total_sum
