        for i in range(len(s) - 1):
            d1 = int(s[i])
            d2 = int(s[i+1])

            # Check if digits are adjacent (always true in loop) and not equal
            if d1 != d2:
                # Check if the counts match the numeric values
                if digit_counts[d1] == d1 and digit_counts[d2] == d2:
                    return str(d1) + str(d2)

