                # Calculate intersection
                common = set(properties[i]) & set(properties[j])
                if len(common) >= k:
                    adj[i].append(j)
                    adj[j].append(i)

        # Count connected components using DFS
        visited = [False] * n
        count = 0

        for i in range(n):
            if not visited[i]:
                count += 1
                stack = [i]
                while stack:
                    node = stack.pop()
                    if not visited[node]:
                        visited[node] = True
                        for neighbor in adj[node]:
                            if not visited[neighbor]:
                                stack.append(neighbor)

        return count
